hubs.smoke:
$token = Get-HubEnv 'YANDEX_DIRECT_TOKEN'
if (-not $token) { throw 'no token' }
$h = @{ Authorization = 'Bearer ' + $token; 'Accept-Language' = 'ru' }
$b = '{"method":"get","params":{"SelectionCriteria":{},"FieldNames":["Id","Name"]}}'
$r = Invoke-RestMethod -Uri ($base + '/json/v5/campaigns') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $b -TimeoutSec 30
if ($r.error) {
    $code = $r.error.error_code
    Write-Output ('API-ERROR: ' + $code + ' ' + $r.error.error_string + ' — ' + $r.error.error_detail)
    if ($code -eq 58) { Write-Output 'STATUS: BLOCKED (access request not approved)'; exit 2 }
    if ($code -eq 53) { Write-Output 'STATUS: FAIL (token rejected)'; exit 1 }
    Write-Output 'STATUS: FAIL (live smoke: API error)'; exit 1
}
"campaigns: $($r.result.Campaigns.Count) host=$base"

$key = Get-HubEnv 'YC_API_KEY'
$folder = Get-HubEnv 'YC_FOLDER_ID'
if (-not $key -or -not $folder) { throw 'no key or folder' }
$h = @{ Authorization = 'Api-key ' + $key }
$b = @{ folderId = $folder; phrase = 'натяжные потолки'; numPhrases = 5 } | ConvertTo-Json -Compress
$r = Invoke-RestMethod -Uri 'https://searchapi.api.cloud.yandex.net/v2/wordstat/topRequests' -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($b)) -TimeoutSec 30
if ($r.error) { throw ('API error: ' + ($r.error | ConvertTo-Json -Compress)) }
if (-not ($r.PSObject.Properties.Name -contains 'totalCount')) { throw 'no totalCount in response' }
"total: $($r.totalCount)"
